INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (24, 1, 'Q24', 'RANKING', 'sql', 'sql', 'WITH oh AS (SELECT sku, SUM(on_hand)::numeric AS on_hand FROM scm.inventory_daily WHERE snap_date = DATE ''2026-11-08'' GROUP BY sku), d AS (SELECT sku, SUM(qty)::numeric / 28 AS daily FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'' GROUP BY sku) SELECT oh.sku FROM oh JOIN d ON d.sku = oh.sku WHERE d.daily > 0 ORDER BY oh.on_hand / d.daily ASC, oh.sku LIMIT 5', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
