INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (590, 73, 'Q54', 'METRIC', 'sql', 'sql', 'WITH w AS (SELECT f.week_start, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 WHERE f.sku = ''SKU-033'' AND f.location_id = ''LOC-04'' GROUP BY f.week_start, f.forecast_qty) SELECT 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w LIMIT 200', true, NULL, 'OK', 1, 0, 0, 11, NULL, NULL, NULL, NULL, NULL, NULL);
