INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1449, 164, 'Q40', 'METRIC', 'sql', 'tool', NULL, false, 'TOOL_SELECTION', 'OK', 2, 2436, 77, 4759, 'no column matches expected column cnt', 'tool', 'below_safety_stock', '{"output":"count"}', '리드타임이 7일인 SKU-거점 중 현재 안전재고에 못 미치는 것은 17개입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1453, 164, 'Q44', 'RANKING', 'sql', 'sql', 'SELECT fw.week_start, ABS(SUM(sd.qty) - SUM(fw.forecast_qty)) AS diff FROM sales_daily sd JOIN forecast_weekly fw ON sd.sku = fw.sku AND sd.location_id = fw.location_id AND sd.sale_date BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' AND fw.week_start BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' WHERE sd.sku = ''SKU-021'' GROUP BY fw.week_start ORDER BY diff DESC LIMIT 1', false, 'JOIN_AGGREGATION', 'OK', 4, 6732, 374, 21989, 'no column matches expected column week_start', 'sql', NULL, NULL, 'SKU-021의 최근 13주 중 예측과 실적 차이가 가장 컸던 주는 2026-08-10입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1466, 165, 'Q57', 'METRIC', 'sql', 'sql', 'SELECT COUNT(*) FROM inventory_daily i JOIN supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id WHERE i.snap_date = DATE ''2026-11-08'' AND (i.on_hand + i.in_transit)::numeric / NULLIF((SELECT SUM(qty) FROM sales_daily WHERE sku = i.sku AND sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'')::numeric / 28, 0) < p.lead_time_days LIMIT 200', false, 'METRIC_DEFINITION', 'OK', 3, 4459, 199, 11608, 'no column matches expected column cnt', 'sql', NULL, NULL, '재고보유일수가 리드타임보다 짧은 SKU-거점은 221개입니다.', 'VERIFIED');
